import math


def carico_critico(E, I, L, beta):
    return math.pi**2 * E * I / (beta * L) ** 2


def snellezza(L, i, beta):
    return beta * L / i


def verifica_instabilita(N, E, I, L, beta):
    if N < carico_critico(E, I, L, beta):
        return True
    else:
        return False

def media(xs):
    totale = 0
    for x in xs:
        totale += x
    return totale / len(xs)


def dev_std(xs):
    m = media(xs)
    somma = 0
    for x in xs:
        somma += (x - m) ** 2
    return (somma / (len(xs) - 1)) ** 0.5


def fuori_soglia(xs, k):
    m = media(xs)
    s = dev_std(xs)
    fuori = []
    for x in xs:
        if abs(x - m) > k * s:
            fuori.append(x)
    return fuori

def massa_totale(distinta):
    tot = 0.0
    for voce in distinta.values():
        unit = voce.get("massa", 0.0) + massa_totale(voce.get("sotto", {}))
        tot += voce["qta"] * unit
    return tot


def conta_pezzi(distinta, molt=1, acc=None):
    acc = {} if acc is None else acc
    for nome, voce in distinta.items():
        n = molt * voce["qta"]
        acc[nome] = acc.get(nome, 0) + n
        conta_pezzi(voce.get("sotto", {}), n, acc)
    return acc

