def trapezi(f, a, b, n=100):
    h = (b - a) / n
    return h * (f(a) / 2 + sum(f(a + i * h) for i in range(1, n)) + f(b) / 2)


def simpson(f, a, b, n=100):
    if n % 2:
        n += 1
    h = (b - a) / n
    s = f(a) + f(b)
    s += 4 * sum(f(a + i * h) for i in range(1, n, 2))
    s += 2 * sum(f(a + i * h) for i in range(2, n, 2))
    return s * h / 3


def lavoro_molla(k, x1, x2):
    return simpson(lambda x: k * x, x1, x2)

import math


def bisezione(f, a, b, tol=1e-8):
    fa, fb = f(a), f(b)
    if fa * fb > 0:
        raise ValueError("f(a) e f(b) devono avere segno opposto")
    while b - a > tol:
        m = (a + b) / 2
        fm = f(m)
        if fa * fm <= 0:
            b, fb = m, fm
        else:
            a, fa = m, fm
    return (a + b) / 2


def diametro_minimo(F, sigma_amm):
    return bisezione(lambda d: 4 * F / (math.pi * d**2) - sigma_amm, 0.1, 1000)

