import math


class Vettore2D:
    def __init__(self, x, y):
        self.x = float(x)
        self.y = float(y)

    def __repr__(self):
        return f"Vettore2D({self.x:g}, {self.y:g})"

    def __eq__(self, altro):
        if not isinstance(altro, Vettore2D):
            return NotImplemented
        return abs(self.x - altro.x) < 1e-9 and abs(self.y - altro.y) < 1e-9

    def __add__(self, altro):
        return Vettore2D(self.x + altro.x, self.y + altro.y)

    def __sub__(self, altro):
        return Vettore2D(self.x - altro.x, self.y - altro.y)

    def __mul__(self, k):
        return Vettore2D(self.x * k, self.y * k)

    __rmul__ = __mul__

    def __abs__(self):
        return math.hypot(self.x, self.y)

    def angolo(self):
        return math.degrees(math.atan2(self.y, self.x))


def risultante(forze):
    tot = Vettore2D(0, 0)
    for f in forze:
        tot = tot + f
    return tot

def interpreta(riga):
    match riga.split():
        case ["F", F, "a", a]:
            return ("F", float(F), float(a))
        case ["q", q, "da", a, "a", b]:
            return ("q", float(q), float(a), float(b))
        case ["q", q]:
            return ("q", float(q), 0.0, None)
        case _:
            raise ValueError(f"comando non valido: {riga!r}")


