from collections import deque
from itertools import islice


def finestre(iterabile, n):
    buf = deque(maxlen=n)
    for x in iterabile:
        buf.append(x)
        if len(buf) == n:
            yield tuple(buf)


def medie_mobili(iterabile, n):
    for f in finestre(iterabile, n):
        yield sum(f) / n

