import numpy as np


def tabella_tau(diametri, forze):
    d = np.asarray(diametri, dtype=float)[:, None]
    F = np.asarray(forze, dtype=float)[None, :]
    return 4 * F / (np.pi * d**2)


def diametro_minimo(diametri, forze, tau_amm):
    d = np.sort(np.asarray(diametri, dtype=float))
    ok = tabella_tau(d, forze) <= tau_amm
    primo = ok.argmax(axis=0)
    return np.where(ok.any(axis=0), d[primo], np.nan)

import numpy as np


def gauss(A, b):
    A = np.array(A, dtype=float)
    b = np.array(b, dtype=float)
    n = len(b)
    for k in range(n):
        p = k + np.argmax(np.abs(A[k:, k]))
        if abs(A[p, k]) < 1e-12:
            raise ValueError("matrice singolare")
        if p != k:
            A[[k, p]] = A[[p, k]]
            b[[k, p]] = b[[p, k]]
        for i in range(k + 1, n):
            m = A[i, k] / A[k, k]
            A[i, k:] -= m * A[k, k:]
            b[i] -= m * b[k]
    x = np.zeros(n)
    for i in range(n - 1, -1, -1):
        x[i] = (b[i] - A[i, i + 1:] @ x[i + 1:]) / A[i, i]
    return x

